/** A land parcel being researched, presented to builders, or acquired. Property status is tracked separately from the commercial pipeline. */
export interface LandOpportunityCreateInput {
/** City where the parcel is located. */
city?: (Scalars['String'] | null),
/** Street address of the land parcel. Leave blank when not verified. */
propertyAddress?: (Scalars['String'] | null),
/** Zoning classification of the parcel. */
zoning?: (Scalars['String'] | null),
/** Name */
name?: (Scalars['String'] | null),
/** ID */
id?: (Scalars['ID'] | null),
/** Creation date */
createdAt?: (Scalars['DateTime'] | null),
/** The creator of the record */
createdBy?: (ActorCreateInput | null),
/** Deletion date */
deletedAt?: (Scalars['DateTime'] | null),
/** Position */
position?: (Scalars['Position'] | null),
/** Last time the record was changed */
updatedAt?: (Scalars['DateTime'] | null),
/** The workspace member who last updated the record */
updatedBy?: (ActorCreateInput | null),
/** Search vector */
searchVector?: (Scalars['TSVector'] | null),
/** County parcel/APN stored as text. Use with state for duplicate detection. */
parcelNumber?: (Scalars['String'] | null),
/** ZIP code stored as text to preserve leading zeros. */
zipCode?: (Scalars['String'] | null),
/** Verifiable source for the parcel research. Required before marking a parcel Qualified. */
sourceUrl?: (LinksCreateInput | null),
/** Lot area in square feet. Must be zero or positive; negative values are rejected by the validation workflow. */
lotSizeSqFt?: (Scalars['Float'] | null),
/** Property-level status. Kept separate from the commercial pipeline stage on Opportunity. */
opportunityStatus?: (LandOpportunityOpportunityStatusEnum | null),
/** Asking price in USD. Must be zero or positive. */
askingPrice?: (CurrencyCreateInput | null),
/** County where the parcel is located. */
county?: (Scalars['String'] | null),
/** Automatically stamped when Opportunity Status becomes Presented to Builder. */
presentedAt?: (Scalars['DateTime'] | null),
/** Builder currently assigned to / most interested in this parcel. A builder can be assigned to many parcels; multiple interested builders per parcel would need a junction object. */
assignedBuilderId?: (Scalars['ID'] | null),
/** Builder currently assigned to / most interested in this parcel. A builder can be assigned to many parcels; multiple interested builders per parcel would need a junction object. */
assignedBuilder?: (CompanyRelationInput | null),
/** Estimated market value of the parcel in USD. */
estimatedValue?: (CurrencyCreateInput | null),
/** Channel that originated the land lead. */
leadSource?: (LandOpportunityLeadSourceEnum | null),
/** Person responsible for the owner/seller outreach. Verified contact details live on the Person record. */
ownerContactId?: (Scalars['ID'] | null),
/** Person responsible for the owner/seller outreach. Verified contact details live on the Person record. */
ownerContact?: (PersonRelationInput | null),
/** Legal owner name as recorded (individual, LLC, trust, etc.). */
ownerName?: (Scalars['String'] | null),
/** Offer amount proposed to the seller, in USD. */
proposedOffer?: (CurrencyCreateInput | null),
/** Counteroffer amount from the seller, in USD. */
counteroffer?: (CurrencyCreateInput | null),
/** Readiness of the seller contract. Does not imply the deal is closed. */
contractReadiness?: (LandOpportunityContractReadinessEnum | null),
/** Sub-status of the seller price negotiation. */
negotiationStatus?: (LandOpportunityNegotiationStatusEnum | null),
/** Interest level of the owner/seller in selling the parcel. */
sellerInterest?: (LandOpportunitySellerInterestEnum | null),
/** Title company handling the transaction. */
titleCompany?: (Scalars['String'] | null),
/** Scheduled or actual closing date. */
closingDate?: (Scalars['Date'] | null),
/** When the contract was sent to the seller. Sending a contract does NOT close the transaction. */
contractSentAt?: (Scalars['DateTime'] | null),
/** When the seller signed the contract. */
contractSignedAt?: (Scalars['DateTime'] | null),
/** Contract/title transaction sub-status. Seller Stage is the overall acquisition pipeline. */
transactionStatus?: (LandOpportunityTransactionStatusEnum | null),
/** Seller/acquisition pipeline managed by the n8n workflow. */
sellerStage?: (LandOpportunitySellerStageEnum | null),
/** Property type of the parcel, used to match against Buybox.propertyTypes. */
propertyType?: (LandOpportunityPropertyTypeEnum | null),
/** Two-letter US state code (e.g. TX, GA, NC, AL, FL). */
state?: (Scalars['String'] | null),
/** Resumo/transcrição da última ligação, enviado pelo n8n. */
lastCallSummary?: (Scalars['String'] | null),
/** false quando o n8n grava um novo resultado de ligação; o Workflow do CRM marca true depois de mover o Kanban. */
callOutcomeProcessed?: (Scalars['Boolean'] | null),
/** Resultado da ligação com o vendedor, enviado pelo n8n. */
callOutcome?: (LandOpportunityCallOutcomeEnum | null),
/** Data/hora da última ligação, enviada pelo n8n. */
lastCallAt?: (Scalars['DateTime'] | null),
/** Seller/owner callback number (E.164) */
phone?: (Scalars['String'] | null),email?: (Scalars['String'] | null),
/** Dialer contact pipeline state (mirrors opportunityStatus vocabulary) */
coldCallStatus?: (LandOpportunityColdCallStatusEnum | null)}


